def knapsack_01(items, capacity):
    if type(capacity) is not int or capacity < 0:
        raise ValueError("invalid capacity")
    if any(type(weight) is not int or weight <= 0 or type(value) is not int or value < 0
           for weight, value in items):
        raise ValueError("expected positive integer weights and nonnegative integer values")
    best = [0] * (capacity + 1)
    for weight, value in items:
        for room in range(capacity, weight - 1, -1):
            best[room] = max(best[room], best[room - weight] + value)
    return best[capacity]

print(knapsack_01([(2, 3), (3, 4), (4, 5)], 5))
print(knapsack_01([(2, 3)], 4))
print(knapsack_01([], 5))

MOD = 1000000007

def count_ways(amount, coins):
    if type(amount) is not int or not 0 <= amount <= 20000:
        raise ValueError('invalid amount')
    if not 1 <= len(coins) <= 100 or any((type(c) is not int or not 1 <= c <= 20000 for c in coins)):
        raise ValueError('invalid denominations')
    if len(set(coins)) != len(coins):
        raise ValueError('denominations must be distinct')
    ways = [0] * (amount + 1)
    ways[0] = 1
    for coin in coins:
        for total in range(coin, amount + 1):
            ways[total] = (ways[total] + ways[total - coin]) % MOD
    return [str(ways[amount])]

print(count_ways(3, [1, 2]))
print(count_ways(0, [2, 5]))
print(count_ways(3, [2]))

