def lcs(a, b):
    if not 1 <= len(a) <= 1500 or not 1 <= len(b) <= 1500:
        raise ValueError('invalid sequence lengths')
    if any((type(x) is not int or abs(x) > 10 ** 9 for seq in (a, b) for x in seq)):
        raise ValueError('invalid sequence value')
    if len(b) > len(a):
        (a, b) = (b, a)
    old = [0] * (len(b) + 1)
    for x in a:
        new = [0] * (len(b) + 1)
        for (j, y) in enumerate(b, 1):
            new[j] = old[j - 1] + 1 if x == y else max(old[j], new[j - 1])
        old = new
    return [str(old[-1])]

print(lcs([1, 2, 1], [2, 1, 2]))
print(lcs([7, 7], [7]))
print(lcs([1], [2]))

