def edit_distance(a, b):
    if any((type(s) is not str or not 1 <= len(s) <= 1000 or any((not 'a' <= ch <= 'z' for ch in s)) for s in (a, b))):
        raise ValueError('invalid strings')
    if len(b) > len(a):
        (a, b) = (b, a)
    old = list(range(len(b) + 1))
    for (i, x) in enumerate(a, 1):
        new = [i] + [0] * len(b)
        for (j, y) in enumerate(b, 1):
            new[j] = min(old[j] + 1, new[j - 1] + 1, old[j - 1] + (x != y))
        old = new
    return [str(old[-1])]

print(edit_distance('cat', 'cut'))
print(edit_distance('ab', 'ba'))
print(edit_distance('a', 'b'))

