def valid_intervals(intervals):
    if not 1 <= len(intervals) <= 100000:
        raise ValueError('invalid interval count')
    if any((type(s) is not int or type(e) is not int or (not 0 <= s < e <= 10 ** 9) for (s, e) in intervals)):
        raise ValueError('invalid half-open interval')

def max_meetings(intervals):
    valid_intervals(intervals)
    chosen = 0
    last_end = None
    for (start, end) in sorted(intervals, key=lambda item: (item[1], item[0])):
        if last_end is None or start >= last_end:
            chosen += 1
            last_end = end
    return [str(chosen)]

print(max_meetings([(0, 6), (1, 2), (2, 3), (3, 4)]))
print(max_meetings([(1, 2), (2, 3)]))

