def min_coins(coins, amount):
    """Source allows repeated denominations; they do not create new choices."""
    unreachable = amount + 1
    dp = [0] + [unreachable] * amount
    for total in range(1, amount + 1):
        for coin in coins:
            if coin <= total:
                dp[total] = min(dp[total], dp[total - coin] + 1)
    return [str(dp[amount] if dp[amount] <= amount else -1)]

print(min_coins([2, 2], 3))
print(min_coins([9], 0))
print(min_coins([1, 5, 11], 15))
